<?php
require_once __DIR__.'/verificar_sesion.php';$db=conexion();$desde=$_GET['desde']??date('Y-m-01');$hasta=$_GET['hasta']??date('Y-m-d');$error='';$filas=false;$fecha_ok=function($v){$d=DateTime::createFromFormat('!Y-m-d',$v);return $d&&$d->format('Y-m-d')===$v;};if(!$fecha_ok($desde)||!$fecha_ok($hasta))$error='Selecciona fechas válidas.';elseif($desde>$hasta)$error='La fecha inicial no puede ser posterior a la fecha final.';if($error===''){$stmt=$db->prepare('SELECT p.id,p.fecha,p.total,p.estado,CONCAT(c.nombre," ",c.apellidos) cliente FROM pedidos p INNER JOIN clientes c ON c.id=p.cliente_id WHERE DATE(p.fecha) BETWEEN ? AND ? ORDER BY p.fecha DESC');$stmt->bind_param('ss',$desde,$hasta);$stmt->execute();$filas=$stmt->get_result();}$titulo='Informe de ventas';require __DIR__.'/includes/encabezado.php';?>
<main class="contenido"><h1>Informe de ventas</h1><p>Consulta las ventas realizadas entre dos fechas.</p><?php if($error):?><p class="error"><?php echo e($error);?></p><?php endif;?><form class="filtros-fecha"><label>Desde <input type="date" name="desde" value="<?php echo e($desde);?>" required></label><label>Hasta <input type="date" name="hasta" value="<?php echo e($hasta);?>" required></label><button class="boton">Consultar</button><a class="boton" href="exportar.php?desde=<?php echo urlencode($desde);?>&hasta=<?php echo urlencode($hasta);?>">Descargar CSV</a></form><?php if($filas):?><div class="tabla-scroll"><table><thead><tr><th>Pedido</th><th>Fecha</th><th>Cliente</th><th>Estado</th><th>Total</th></tr></thead><tbody><?php $suma=0;$pendiente=0;$cancelado=0;while($v=$filas->fetch_assoc()):if($v['estado']==='Entregado')$suma+=(float)$v['total'];elseif($v['estado']==='Cancelado')$cancelado+=(float)$v['total'];else $pendiente+=(float)$v['total'];?><tr><td><?php echo (int)$v['id'];?></td><td><?php echo e($v['fecha']);?></td><td><?php echo e($v['cliente']);?></td><td><?php echo e($v['estado']);?></td><td><?php echo e(precio_texto($v['total']));?></td></tr><?php endwhile;?></tbody><tfoot><tr><th colspan="4">Ventas entregadas</th><th><?php echo e(precio_texto($suma));?></th></tr></tfoot></table></div><p><strong>Ventas entregadas:</strong> <?php echo e(precio_texto($suma));?> · <strong>Pedidos pendientes/en proceso:</strong> <?php echo e(precio_texto($pendiente));?> · <strong>Cancelados:</strong> <?php echo e(precio_texto($cancelado));?></p><?php $top=$db->prepare("SELECT COALESCE(pr.nombre,'Producto eliminado') producto,SUM(d.cantidad) unidades,SUM(d.cantidad*d.precio) importe FROM detalle_pedido d INNER JOIN pedidos p ON p.id=d.pedido_id LEFT JOIN productos pr ON pr.id=d.producto_id WHERE DATE(p.fecha) BETWEEN ? AND ? AND p.estado<>'Cancelado' GROUP BY d.producto_id,pr.nombre ORDER BY unidades DESC LIMIT 10");$top->bind_param('ss',$desde,$hasta);$top->execute();$mas=$top->get_result();?><h2>Productos más vendidos (sin pedidos cancelados)</h2><div class="tabla-scroll"><table><thead><tr><th>Producto</th><th>Unidades</th><th>Importe</th></tr></thead><tbody><?php while($m=$mas->fetch_assoc()):?><tr><td><?php echo e($m['producto']);?></td><td><?php echo (int)$m['unidades'];?></td><td><?php echo e(precio_texto($m['importe']));?></td></tr><?php endwhile;?></tbody></table></div><?php $top->close();?><?php endif;?></main>
<?php if(isset($stmt))$stmt->close();$db->close();require __DIR__.'/includes/pie.php';?>